parameters.jsCode:
const historial = $json.historial || [];

const mensajesLimpios = historial
  .filter(m => {
    // Solo conversación usuario/asistente
    if (!['human', 'ai'].includes(m.type)) {
      return false;
    }

    // Eliminar mensajes internos de tool calling
    if (
      m.type === 'ai' &&
      typeof m.content === 'string' &&
      m.content.startsWith('Calling ')
    ) {
      return false;
    }

    return true;
  })
  .slice(-8)
  .map(m => ({
    rol: m.type === 'human' ? 'CLIENTE' : 'ASISTENTE',
    contenido: m.content
  }));

const contextoConversacion = mensajesLimpios
  .map(m => `${m.rol}: ${m.contenido}`)
  .join('\n\n');

return [
  {
    json: {
      lead_id: $json.lead_id,
      session_id: $json.session_id,
      nombre: $json.nombre,
      empresa: $json.empresa,
      telefono: $json.telefono,
      email: $json.email,
      contexto_conversacion: contextoConversacion
    }
  }
];

const textoOriginal = String($json.text ?? '').trim();

// Tomar únicamente el objeto JSON que esté entre la primera { y la última }
const inicio = textoOriginal.indexOf('{');
const fin = textoOriginal.lastIndexOf('}');

if (inicio === -1 || fin === -1 || fin < inicio) {
  throw new Error(
    'No se encontró un objeto JSON válido en la respuesta del LLM: ' + textoOriginal
  );
}

const textoJson = textoOriginal.slice(inicio, fin + 1);

let resumen;

try {
  resumen = JSON.parse(textoJson);
} catch (error) {
  throw new Error(
    'No se pudo interpretar la respuesta del LLM como JSON: ' + textoOriginal
  );
}

const contexto = $('preparar_contexto_consulta').first().json;

return [
  {
    json: {
      lead_id: contexto.lead_id,
      session_id: contexto.session_id,
      nombre: contexto.nombre,
      empresa: contexto.empresa,
      telefono: contexto.telefono,
      email: contexto.email,

      motivo_derivacion: resumen.motivo_derivacion || null,
      resumen_consulta: resumen.resumen_consulta || null
    }
  }
];

conditions.leftValue:
={{
  Boolean(
    String($json.nombre ?? '').trim() &&
    (
      String($json.telefono ?? '').trim() ||
      String($json.email ?? '').trim()
    ) &&
    String($json.motivo_derivacion ?? '').trim() &&
    String($json.resumen_consulta ?? '').trim() &&
    String($json.session_id ?? '').trim() &&
    Number($json.lead_id || 0) > 0
  )
}}

